<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {copy,validRule} from '../payrollUi'
import {storeToday} from '../time'
import {applyUpgradeValue} from '../payTemplateUpgrade'
import type {UpgradePreview,UpgradeResolution,UpgradeWrite} from '../payTemplateUpgrade'
import type {TemplateAdoption} from '../payTemplatePublication'
import type {PayChange} from '../payChanges'
import type {PayRule} from '../payrollTypes'
import {changeField,changeValue} from '../payChangeDisplay'
import PayRuleFields from './PayRuleFields.vue'
const props=defineProps<{adoptions:TemplateAdoption[];targetVersion:number;adoptionDates?:Record<string,string>;request?:PayChange|null}>(),emit=defineEmits<{close:[];saved:[request:PayChange]}>(),{api,english,current,message}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
const date=ref(props.request?.effectiveDate||storeToday()),adoptionId=ref(props.request?.adoptionId||props.adoptions[0]?.id||''),preview=ref<UpgradePreview|null>(null),derived=ref<PayRule|null>(null),choices=ref<Record<string,UpgradeResolution['choice']>>({}),reason=ref(props.request?.content.reason||''),error=ref(''),busy=ref(false),id=props.request?.id||crypto.randomUUID();let revision=0
onBeforeUnmount(()=>{revision++})
watch(()=>[date.value,adoptionId.value,props.targetVersion],()=>{revision++;preview.value=null;derived.value=null;choices.value={};error.value='';busy.value=false})
const adoption=computed(()=>props.adoptions.find(a=>a.id===adoptionId.value))
async function load(){const a=adoption.value;if(!a||!date.value||busy.value)return;const rev=++revision;busy.value=true;preview.value=null;derived.value=null;choices.value={};error.value='';try{const p=await api().get<UpgradePreview>(`/pay-template-library/${a.masterId}/upgrade-preview?adoptionId=${a.id}&releaseVersion=${props.targetVersion}&effectiveDate=${date.value}`);if(!current()||rev!==revision)return;preview.value=p;derived.value=copy(props.request?.content.derivedRule||p.baseAdoption.rule);for(const c of props.request?.content.upgrade?.resolutions||[])choices.value[c.path]=c.choice}catch(e){if(rev===revision)error.value=message(e)}finally{if(rev===revision)busy.value=false}}
function choose(path:string,choice:UpgradeResolution['choice']){if(!['local','target','custom'].includes(choice)){delete choices.value[path];return}choices.value[path]=choice;const d=preview.value?.differences.find(d=>d.path===path);if(d&&derived.value&&choice!=='custom')applyUpgradeValue(derived.value,path,d[choice])}
async function save(){const saveRevision=revision,p=preview.value,rule=derived.value;if(!p||!rule||busy.value)return;error.value='';if(p.differences.some(d=>d.conflict&&!choices.value[d.path])||!reason.value.trim()||!validRule(rule)){error.value=x('请明确处理每个冲突、核对完整规则并填写理由。','Resolve every conflict, check full rules and enter a reason.');return}const body:UpgradeWrite={expectedRevision:props.request?.revision||0,companyId:p.baseAdoption.companyId,adoptionId:p.baseAdoption.id,targetReleaseVersion:p.targetRelease.version,effectiveDate:p.effectiveDate,expectedLatestStoreVersion:p.expectedLatestStoreVersion,previewHash:p.previewHash,derivedRule:copy(rule),resolutions:p.differences.filter(d=>d.conflict).map(d=>({path:d.path,choice:choices.value[d.path]!})),reason:reason.value.trim()};busy.value=true;try{const r=await api().put<PayChange>(`/pay-change-requests/${id}/upgrade`,body);if(current()&&revision===saveRevision)emit('saved',r)}catch(e){if(current())error.value=message(e)}finally{if(current())busy.value=false}}
</script>
<template><section class="wf-section" aria-label="template-upgrade"><h3>{{x('门店模板升级申请','Store template upgrade request')}}</h3><p class="wf-hint">{{x('升级只生成本店候选草稿，须继续提交和审批；不会替换员工方案。保留当前版本无需写入。','Upgrade saves a store candidate draft, requiring submission and approval. Employee profiles are unchanged. Keeping the current version writes nothing.')}}</p><div class="wf-grid"><label>{{x('本店基底','Store baseline')}}<select v-model="adoptionId" :disabled="busy||!!request" :aria-label="x('升级本店基底','Upgrade baseline')"><option v-for="a in adoptions" :key="a.id" :value="a.id">{{a.name}} · {{x('母版／本店版本','Master / store version')}} {{a.releaseVersion}} / {{a.storeVersion}} {{adoptionDates?.[a.id]?x('批准待生效','Approved future')+' '+adoptionDates[a.id]:''}}</option></select></label><label>{{x('升级生效日期','Upgrade effective date')}}<input v-model="date" type="date" :disabled="busy||!!request" :aria-label="x('升级生效日期','Upgrade effective date')"></label></div><p>{{x('固定目标母版版本','Fixed target release')}} {{targetVersion}}</p><button :disabled="busy||!adoptionId||!date" @click="load">{{x('读取三方差异','Read three-way differences')}}</button><p v-if="error" role="alert">{{error}}</p><template v-if="preview&&derived"><p>{{x('旧母版','Old master')}} {{preview.oldRelease.version}} → {{x('目标母版','Target master')}} {{preview.targetRelease.version}} · {{x('本店版本','Store version')}} {{preview.baseAdoption.storeVersion}} · {{preview.effectiveDate}}</p><p v-if="!preview.differences.length">{{x('规则没有差异，仍可保留当前版本。','Rules have no differences; current version can be kept.')}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{x('字段','Field')}}</th><th>{{x('旧母版','Old master')}}</th><th>{{x('本店修改','Local store')}}</th><th>{{x('目标母版','Target master')}}</th><th>{{x('选择','Choice')}}</th></tr></thead><tbody><tr v-for="d in preview.differences" :key="d.path"><td>{{english()?changeField(d.path,true):d.label}}<strong v-if="d.conflict"> · {{x('冲突','Conflict')}}</strong></td><td>{{changeValue(d.oldBase,english())}}</td><td>{{changeValue(d.local,english())}}</td><td>{{changeValue(d.target,english())}}</td><td><select :value="choices[d.path]||''" :disabled="busy" :aria-label="x('冲突处理 ','Resolve ')+d.path" @change="choose(d.path,($event.target as HTMLSelectElement).value as UpgradeResolution['choice'])"><option value="">{{d.conflict?x('必须明确选择','Explicit choice required'):x('保留本店值，可调整','Keep local, may adjust')}}</option><option value="local">{{x('保留本店值','Keep local')}}</option><option value="target">{{x('采用目标值','Use target')}}</option><option value="custom">{{x('人工调整完整规则','Edit complete rule')}}</option></select></td></tr></tbody></table></div><h4>{{x('完整拟采用规则（可编辑）','Complete proposed rule (editable)')}}</h4><PayRuleFields preserve-item-ids :rule="derived" :disabled="busy"/><label>{{x('升级理由','Upgrade reason')}}<textarea v-model="reason" :disabled="busy" maxlength="1000" :aria-label="x('升级理由','Upgrade reason')"/></label><button class="primary" :disabled="busy" @click="save">{{x('保存升级草稿','Save upgrade draft')}}</button></template><button :disabled="busy" @click="emit('close')">{{x('保留当前版本','Keep current version')}}</button></section></template>
<style scoped>td{min-width:8rem;max-width:20rem;white-space:pre-wrap;overflow-wrap:anywhere}select,textarea{max-width:100%;box-sizing:border-box}</style>
